(function(){'use strict';
/* JAH The Marine Biology generator — jahdb-marine-biology-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-MARB-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Ocean Zones", "title": "The Ocean Zones: From Sunlight to Trench", "desc": "The ocean is layered by light and depth into zones that structure all marine life. The sunlight zone (epipelagic, 0-200 m) hosts photosynthesis and most familiar life. The twilight zone (mesopelagic, 200-1000 m) holds the largest fish biomass on Earth - lanternfish migrating nightly. The midnight zone (bathypelagic, 1000-4000 m), the abyss (4000-6000 m), and the hadal trenches below complete the descent into cold, dark, high-pressure water.\nEach zone filters life by its physics: light fades exponentially, temperature drops toward 2-4 C, pressure rises one atmosphere every 10 m. Organisms adapt with bioluminescence, slow metabolisms, and pressure-resistant biochemistry. The zones are not just depth bands but distinct worlds with distinct communities, connected by the daily vertical migrations and sinking particles that move energy downward.", "how": "Marine biologists sample zones with nets, trawls, ROVs, and submersibles matched to depth ratings, measuring temperature, salinity, oxygen, and light with CTD casts. They map species to zones from catch and observation data, tracking diel vertical migration with acoustics. Zone frameworks organize everything from textbook chapters to conservation planning - protecting the twilight zone's fish biomass, for instance, requires thinking in three dimensions, not just surface area.", "keys": ["Epipelagic (0-200 m): sunlight and photosynthesis.", "Mesopelagic (200-1000 m): twilight zone, Earth's largest fish biomass.", "Bathypelagic, abyssal, hadal: dark, cold, high-pressure worlds.", "Light, temperature, and pressure filter life by zone.", "Vertical migration and sinking particles connect the zones."], "reqs": ["Depth, light, temperature, oxygen profiles (CTD data).", "Depth-rated sampling gear.", "Acoustic or visual migration observations."], "stds": ["Depth zones per standard oceanographic definitions.", "CTD calibration per WOCE standards."], "cites": ["Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019.", "Levinton JS. Marine Biology: Function, Biodiversity, Ecology. 4th ed. Oxford; 2013."], "demo": "#!/usr/bin/env python3\n\"\"\"Ocean zones: light and pressure vs depth.\"\"\"\nimport math\nprint(\" depth (m)   light (%)    pressure (atm)\")\nfor z in (0, 50, 200, 1000, 4000, 11000):\n    light = 100 * math.exp(-z / 60)  # euphotic attenuation hint\n    p = 1 + z / 10\n    print(f\"  {z:5d}      {light:8.2f}      {p:7.0f}\")\n"}, {"tier": "Foundations", "g": "Ocean Zones", "title": "Seawater Chemistry Basics", "desc": "Seawater is a complex solution averaging 35 parts per thousand salinity - mostly sodium and chloride, with magnesium, sulfate, calcium, and potassium making up nearly all the rest. These major ions hold constant ratios everywhere (Marcet's principle), so measuring chlorinity gives salinity. Dissolved gases - oxygen, carbon dioxide, nitrogen - and nutrients (nitrate, phosphate, silicate) vary with biology and drive productivity.\nThe carbonate system buffers ocean pH near 8.1 and governs CO2 exchange with the atmosphere: dissolved CO2 forms carbonic acid, bicarbonate, and carbonate in equilibrium. Adding atmospheric CO2 shifts the balance, lowering pH and carbonate-ion concentration - ocean acidification, which threatens shell-builders. Density, set by temperature and salinity together, drives the deep thermohaline circulation.", "how": "Oceanographers measure salinity by conductivity (practical salinity scale), oxygen by Winkler titration or sensors, nutrients by colorimetric autoanalyzers, and carbonate parameters by titration and spectroscopy. They use temperature-salinity diagrams to identify water masses and trace circulation. Monitoring programs track acidification with high-precision pH and alkalinity time series at stations like Hawaii Ocean Time-series. Every biological study interprets its organisms against this chemical backdrop.", "keys": ["Average salinity 35 ppt; major ions in constant ratios.", "Carbonate system buffers pH and controls CO2 exchange.", "Ocean acidification: more CO2, lower pH, less carbonate ion.", "Nutrients (N, P, Si) limit productivity regionally.", "Temperature + salinity set density and drive deep circulation."], "reqs": ["Salinity via conductivity; temperature; pressure.", "Carbonate parameters (two of: pH, alkalinity, DIC, pCO2).", "Nutrient concentrations for productivity context."], "stds": ["Practical salinity scale (PSS-78).", "Carbonate measurements per Dickson lab best practices."], "cites": ["Libes SM. Introduction to Marine Biogeochemistry. 2nd ed. Wiley; 2009.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Seawater density from temperature and salinity (simplified).\"\"\"\n# linearized equation of state hint\nprint(\"  T (C)   S (ppt)   density (kg/m3)\")\nfor T, S in ((20, 35), (10, 35), (2, 35), (20, 30), (2, 34.9)):\n    rho = 1000 + 0.8 * S - 0.15 * T\n    print(f\"   {T:2d}     {S:4.1f}      {rho:7.1f}\")\n"}, {"tier": "Foundations", "g": "Marine Life", "title": "Phytoplankton: The Ocean's Producers", "desc": "Phytoplankton - drifting photosynthetic microbes including diatoms, dinoflagellates, and coccolithophores - produce roughly half of Earth's oxygen and form the base of nearly every marine food web. Diatoms build glass (silica) frustules of stunning geometry; coccolithophores armor themselves with chalk plates that make ocean blooms visible from space.\nBlooms follow light and nutrients: spring blooms explode when stratification traps phytoplankton in sunlit surface water. Some dinoflagellates make toxins causing harmful algal blooms (red tides) that poison shellfish and kill fish. Satellite ocean-color sensors map chlorophyll globally, tracking the planet's primary production in near-real time - the pulse of the living ocean.", "how": "Biological oceanographers sample with nets and bottles, identify by microscopy and pigments (HPLC), and measure production with carbon-14 or oxygen methods. Satellites extend ship data globally via chlorophyll algorithms calibrated against field measurements. Harmful-bloom programs monitor cell counts and toxins, closing shellfish beds when thresholds are exceeded. Iron-fertilization experiments test the nutrient-limitation hypothesis that shapes whole-ocean productivity patterns.", "keys": ["Drifting photosynthesizers making ~half of Earth's oxygen.", "Diatoms (silica), dinoflagellates, coccolithophores (chalk).", "Blooms follow light plus nutrients; spring blooms are the classic.", "Some species make toxins - harmful algal blooms and red tides.", "Satellites map global chlorophyll in near-real time."], "reqs": ["Light and nutrient fields for the region and season.", "Taxonomic ID (microscopy, pigments, DNA).", "Production measurement method stated."], "stds": ["Chlorophyll by fluorometry/HPLC per JGOFS protocols.", "HAB toxin monitoring per regulatory thresholds."], "cites": ["Falkowski PG, Raven JA. Aquatic Photosynthesis. 2nd ed. Princeton; 2007.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Bloom growth: exponential phytoplankton increase.\"\"\"\nimport math\nN0, mu = 1e3, 1.0  # cells/L, per day\nprint(\" day    cells/L\")\nfor t in range(0, 15, 2):\n    print(f\"  {t:2d}    {N0*math.exp(mu*t):.2e}\")\n"}, {"tier": "Foundations", "g": "Marine Life", "title": "Zooplankton and the Food Web", "desc": "Zooplankton - drifting animals from microscopic copepods to jellyfish - graze phytoplankton and feed everything above: fish larvae, whales, seabirds. Copepods, the most numerous animals on Earth, dominate; krill form the great Southern Ocean swarms that sustain whales, seals, and penguins.\nThe classic food chain (phytoplankton to copepods to fish) is now joined by the microbial loop: dissolved organic matter feeds bacteria, which flagellates and ciliates return to the main web. Diel vertical migration - the largest animal migration on Earth, happening daily - moves zooplankton between deep daytime refuge and surface nighttime feeding, shuttling carbon downward.", "how": "Plankton ecologists tow fine-mesh nets (bongo, MOCNESS) at discrete depths, preserve and count under microscopes, and increasingly image in situ with cameras and acoustics. They measure grazing with bottle incubations and trace energy flow with stable isotopes. Fisheries models depend on zooplankton production estimates - larval fish survival hinges on matching their first feeding to plankton blooms (the match-mismatch hypothesis).", "keys": ["Copepods: Earth's most numerous animals; krill feed the Southern Ocean.", "The microbial loop recycles dissolved organics back to the food web.", "Diel vertical migration is the planet's largest daily animal migration.", "Zooplankton production sets larval fish survival.", "Nets, imaging, and acoustics sample them."], "reqs": ["Depth-stratified net or optical sampling.", "Taxonomic ID to functional group.", "Coincident phytoplankton/food measurements."], "stds": ["Plankton sampling per standard net protocols (mesh, tow speed).", "Biomass conversions per published length-weight regressions."], "cites": ["Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019.", "Harris R et al., eds. ICES Zooplankton Methodology Manual. Academic Press; 2000."], "demo": "#!/usr/bin/env python3\n\"\"\"Match-mismatch: larval survival vs bloom timing.\"\"\"\n# survival peaks when larvae hatch near bloom peak\nbloom_peak = 100  # day of year\nfor hatch in (80, 90, 100, 110, 120):\n    survival = max(0.0, 1 - abs(hatch - bloom_peak) / 40)\n    print(f\"  hatch day {hatch}: survival index {survival:.2f}\")\n"}, {"tier": "Foundations", "g": "Ecosystems", "title": "Coral Reef Basics", "desc": "Coral reefs are built by colonial cnidarians - coral polyps - that secrete calcium-carbonate skeletons and host symbiotic zooxanthellae algae, which photosynthesize and feed the coral. This partnership lets reefs thrive in nutrient-poor tropical waters, building the most biodiverse marine ecosystems: a quarter of marine species on less than 1% of ocean area.\nReef types trace Darwin's subsidence theory: fringing reefs hug shores, barrier reefs stand offshore behind lagoons, atolls ring sunken volcanoes. Reefs protect coastlines, sustain fisheries, and support tourism economies - ecosystem services valued in the hundreds of billions. They grow only in warm, clear, shallow, sunlit water, which is also what makes them vulnerable.", "how": "Reef biologists survey with transects and photo-quadrats, measuring coral cover, diversity, and recruitment; they core skeletons for growth and climate records. Monitoring programs (e.g., Reef Check, AIMS long-term monitoring) track cover trends. Restoration grows fragments in nurseries for outplanting. Management uses marine protected areas, water-quality controls, and fishing limits - local stressors managers can actually fix while global warming is addressed.", "keys": ["Coral polyps + zooxanthellae symbiosis build reefs in poor waters.", "Most biodiverse marine ecosystem: 25% of species on <1% of area.", "Fringing, barrier, atoll - Darwin's subsidence sequence.", "Coastline protection, fisheries, tourism: huge ecosystem services.", "Need warm, clear, shallow, sunlit water."], "reqs": ["Temperature, light, water-quality regime.", "Coral cover and diversity survey method.", "Local stressor inventory (runoff, fishing, development)."], "stds": ["Reef monitoring per Reef Check / AIMS protocols.", "Coral cover by photo-quadrat analysis."], "cites": ["Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019.", "Spalding MD, Ravilious C, Green EP. World Atlas of Coral Reefs. UNEP; 2001."], "demo": "#!/usr/bin/env python3\n\"\"\"Reef carbonate budget: growth vs erosion.\"\"\"\n# net accretion = gross production - bioerosion - dissolution\ngross, erosion = 10.0, 6.0  # kg CaCO3/m2/yr\nnet = gross - erosion\nprint(f\"Gross {gross}, erosion {erosion} -> net {net:+.1f} kg/m2/yr\")\nprint(\"Reef growing\" if net > 0 else \"Reef eroding\")\n"}, {"tier": "Foundations", "g": "Ecosystems", "title": "Kelp Forests", "desc": "Kelp forests are underwater forests of giant brown algae - Macrocystis can grow 60 cm a day to 60 m tall - forming three-dimensional habitat in cold, nutrient-rich coastal waters. They shelter juvenile fish, abalone, and lobsters, and feed urchins, snails, and detritus webs.\nSea otters are the keystone: by eating urchins they prevent urchin barrens, the grazed-down alternative state. Where otters were hunted out, barrens spread; where they returned, forests recovered - a textbook trophic cascade. Kelp also buffers coastlines, cycles nutrients, and draws interest for carbon sequestration, though most kelp carbon is eaten or exported, not buried.", "how": "Kelp ecologists dive transects counting stipes, canopy cover, urchins, and associated species; they track forest-barren transitions with long-term monitoring. Restoration removes urchins or outplants juvenile kelp, increasingly with attention to marine heatwaves that now drive losses. Management balances urchin fisheries (which profit from barrens) against forest ecosystem services. Otter reintroduction remains the most powerful restoration tool demonstrated.", "keys": ["Giant brown algae forming 3D habitat in cold, rich waters.", "Sea otters are keystone: urchin control prevents barrens.", "Forest vs urchin barren are alternative stable states.", "Trophic cascade textbook: otters to urchins to kelp.", "Marine heatwaves now drive major kelp losses."], "reqs": ["Temperature and nutrient regime.", "Urchin density and predator status.", "Canopy and understory survey data."], "stds": ["Kelp forest monitoring per PISCO protocols.", "Urchin density by belt transect."], "cites": ["Dayton PK. Ecology of kelp communities. Ann Rev Ecol Syst 16:215-245; 1985.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Kelp-urchin-otter cascade (illustrative dynamics).\"\"\"\n# simple: kelp declines as urchins rise; otters suppress urchins\nfor otters in (0, 10, 30):\n    urchins = max(0, 50 - 1.5 * otters)\n    kelp = max(0, 100 - 1.8 * urchins)\n    print(f\"  otters {otters:2d} -> urchins {urchins:4.0f}/m2, kelp {kelp:4.0f}% cover\")\n"}, {"tier": "Foundations", "g": "Ecosystems", "title": "Mangroves and Salt Marshes", "desc": "Mangroves (tropical trees with salt-filtering roots) and salt marshes (temperate grasses like Spartina) are intertidal wetlands that punch far above their area: nurseries for shrimp, crabs, and fish; storm and tsunami buffers; and blue-carbon powerhouses burying carbon in anoxic mud for millennia.\nMangrove roots - prop roots, pneumatophores - trap sediment and build land while sheltering juveniles; salt marshes filter runoff and stabilize shorelines. Both face coastal development, aquaculture conversion (especially shrimp ponds replacing mangroves), and sea-level rise. Restoration replants hydrology first - get the tides right and vegetation often returns on its own.", "how": "Wetland ecologists map extent by satellite and drone, core sediments for carbon stocks, and survey nursery function with juvenile fish and invertebrate sampling. Blue-carbon projects quantify sequestration for credits under verified methodologies. Restoration prioritizes hydrological reconnection over planting - tidal flow restored, mangroves recruit naturally. Management weighs aquaculture profits against the storm protection and fisheries wetlands provide free.", "keys": ["Intertidal wetlands: nurseries, storm buffers, blue-carbon stores.", "Mangrove roots trap sediment and shelter juveniles.", "Salt marshes filter runoff and stabilize temperate shores.", "Top threats: development, aquaculture conversion, sea-level rise.", "Restore hydrology first - vegetation often follows."], "reqs": ["Tidal regime and elevation profile.", "Sediment carbon stock measurements.", "Land-use and conversion pressure inventory."], "stds": ["Blue-carbon stock assessment per IPCC wetlands guidance.", "Wetland mapping per standard remote-sensing protocols."], "cites": ["Alongi DM. Mangrove forests: resilience, protection from tsunamis. Estuar Coast Shelf Sci 76:1-13; 2008.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Blue carbon: mangrove soil stock estimate.\"\"\"\narea_ha, depth_m, bulk, C_frac = 100.0, 1.0, 0.8, 0.04  # g/cm3 bulk density\nsoil_t = area_ha * 1e4 * depth_m * bulk * 1000 / 1000  # tonnes soil\nC_t = soil_t * C_frac\nprint(f\"100 ha mangrove, top 1 m: ~{C_t:,.0f} tonnes C stored\")\nprint(f\"= ~{C_t*3.67:,.0f} tonnes CO2 equivalent\")\n"}, {"tier": "Foundations", "g": "Marine Life", "title": "Marine Mammals Overview", "desc": "Marine mammals - whales, dolphins, seals, sea lions, manatees, otters, polar bears - are mammals that returned to the sea, keeping warm blood, air breathing, live birth, and nursing. Cetaceans (whales, dolphins) never leave the water; pinnipeds (seals, sea lions) haul out to breed; sirenians (manatees, dugongs) graze seagrass.\nAdaptations are extreme: blubber and countercurrent heat exchangers against cold, collapsible lungs and myoglobin-rich muscles for hour-long dives, echolocation for hunting in darkness. Baleen whales filter tons of krill; toothed whales hunt squid and fish. Many populations still recover from whaling; new threats are ship strikes, entanglement, noise, and prey shifts with warming.", "how": "Researchers identify individuals by photo-ID (flukes, scars), track with satellite tags, and estimate populations by mark-recapture or line-transect surveys. Acoustics monitor presence and behavior over ocean basins. Conservation uses ship-speed rules, fishing-gear modifications, and noise limits in critical habitat. Strandings networks collect the mortality data that reveals threats - disease, biotoxins, human interaction.", "keys": ["Mammals returned to the sea: warm-blooded, air-breathing, nursing.", "Cetaceans fully aquatic; pinnipeds haul out; sirenians graze.", "Blubber, dive adaptations, echolocation: the survival kit.", "Baleen filter-feeders vs toothed hunters.", "Threats now: ships, entanglement, noise, prey shifts."], "reqs": ["Species ID and population estimate method.", "Critical habitat and migration corridors.", "Threat inventory (ships, gear, noise)."], "stds": ["Abundance estimation per standard line-transect methods.", "Photo-ID catalogs per regional consortia."], "cites": ["Berta A, Sumich JL, Kovacs KM. Marine Mammals. 3rd ed. Academic Press; 2015.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Dive limit: oxygen stores vs metabolic rate (illustrative).\"\"\"\n# aerobic dive limit = O2 stores / diving metabolic rate\nanimals = [(\"Weddell seal\", 60, 2.0), (\"sperm whale\", 120, 1.5), (\"human\", 2, 3.0)]\nfor name, O2_L, rate_L_min in animals:\n    print(f\"  {name:13s}: ADL ~{O2_L/rate_L_min:.0f} min\")\n"}, {"tier": "Foundations", "g": "Marine Life", "title": "Sea Turtles", "desc": "Seven sea turtle species - green, loggerhead, hawksbill, leatherback, Kemp's ridley, olive ridley, flatback - migrate ocean basins between feeding and nesting beaches, navigating by magnetic fields. Leatherbacks, the largest, dive past 1000 m hunting jellyfish in cold water, sustained by countercurrent heat exchange and giant size.\nTemperature-dependent sex determination makes warming a direct threat: hotter nests produce more females, and several populations already skew heavily female. Conservation leans on beach protection, turtle-excluder devices in trawls, and lighting ordinances - hatchlings follow moonlight to the sea and streetlights lead them astray. Arribadas, the mass nesting of ridleys, remain one of nature's great spectacles.", "how": "Biologists flipper- and satellite-tag turtles, patrol nesting beaches counting nests and hatching success, and relocate doomed nests. They manage nest temperatures with shading or irrigation experiments where feminization threatens. Fisheries bycatch is cut with turtle-excluder devices and circle hooks, verified by observer programs. Head-start programs rear hatchlings past the vulnerable early stage, though wild beach protection remains the foundation.", "keys": ["Seven species; ocean-basin migrations by magnetic navigation.", "Leatherbacks dive past 1000 m after jellyfish.", "Temperature sets sex - warming feminizes populations.", "Beach protection, TEDs, lighting ordinances: the conservation toolkit.", "Arribadas: mass synchronized nesting of ridley turtles."], "reqs": ["Nesting beach inventory and protection status.", "Nest temperature monitoring.", "Bycatch rates in regional fisheries."], "stds": ["Nest monitoring per IUCN Marine Turtle Specialist Group protocols.", "TED compliance per fisheries regulations."], "cites": ["Spotila JR. Sea Turtles. Johns Hopkins University Press; 2004.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Nest sex ratio vs incubation temperature (illustrative).\"\"\"\n# pivotal ~29 C; warmer -> more females\nprint(\" mean nest T (C)   % female\")\nfor T in (27, 28, 29, 30, 31, 32):\n    female = 100 / (1 + 10 ** ((29 - T) * 1.2))\n    print(f\"     {T:4.1f}          {female:5.1f}\")\n"}, {"tier": "Foundations", "g": "Marine Life", "title": "Sharks and Rays", "desc": "Sharks and rays are cartilaginous fishes - skeletons of cartilage, not bone - with 500+ shark species from whale sharks (filter-feeding giants) to lanternsharks (palm-sized, glowing). Most are not the apex predators of movies but mesopredators eating fish and invertebrates; all use electroreception (ampullae of Lorenzini) to find prey.\nSlow growth, late maturity, and few young make them exceptionally vulnerable to overfishing - populations collapse fast and recover slowly. Finning for shark-fin soup drove catastrophic declines; finning bans and CITES listings now protect many species. Rays include mantas (gentle filter feeders) and stingrays; sawfish, with their toothed rostra, are among the most endangered marine fishes.", "how": "Researchers tag with acoustic and satellite tags, survey with baited cameras (BRUVS) and longlines, and age vertebrae like tree rings. They estimate populations for stock assessments that set catch limits, and track fin-trade DNA to enforce bans. Conservation combines fisheries management (quotas, finning bans), trade controls (CITES), and protected areas on nursery grounds. Ecotourism (shark diving) increasingly values live sharks over dead ones.", "keys": ["Cartilaginous fishes: 500+ shark species, huge ecological range.", "Electroreception finds prey; most are mesopredators, not monsters.", "Slow life histories make them exceptionally vulnerable to fishing.", "Finning bans and CITES listings are the protection framework.", "Nursery-ground protection targets the most sensitive life stage."], "reqs": ["Species ID and life-history parameters.", "Fisheries catch and fin-trade data.", "Nursery habitat mapping."], "stds": ["Stock assessment per FAO guidelines.", "BRUVS surveys per standard protocols."], "cites": ["Carrier JC, Musick JA, Heithaus MR, eds. Biology of Sharks and Their Relatives. 2nd ed. CRC Press; 2012.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Shark population recovery: slow growth math.\"\"\"\n# logistic recovery with low intrinsic rate r\nK, r, N0 = 1000.0, 0.07, 100.0\nN = N0\nprint(\" year   population\")\nfor yr in range(0, 51, 10):\n    print(f\"  {yr:2d}     {N:6.0f}\")\n    for _ in range(10):\n        N += r * N * (1 - N / K)\n"}, {"tier": "Foundations", "g": "Ocean Zones", "title": "The Deep Sea", "desc": "The deep sea - below 1000 m - is Earth's largest habitat by volume: perpetual darkness, near-freezing water, and crushing pressure (1000 atm in trenches). Life runs on marine snow, the slow rain of surface particles, supplemented by whale falls and chemosynthetic oases at vents and seeps.\nAdaptations astonish: expandable stomachs, lures with symbiotic bacteria, huge eyes or none, redundant lateral lines. Biomass is sparse but biodiversity is high - and overwhelmingly undescribed; a single trawl can yield new species. Mining interests now target seafloor massive sulfides and manganese nodules, raising the defining conservation question of the deep: exploit or protect what we barely know.", "how": "Deep-sea biologists work from research vessels with ROVs, AUVs, submersibles, and landers - expensive, slow, transformative. They image transects, suction-sample specimens, and deploy experiments for years. Environmental DNA now detects species from water samples. Impact assessment for mining uses baseline surveys and plume modeling; recovery experiments show disturbance lasting decades. Every expedition still discovers - the deep sea is the least-known major habitat.", "keys": ["Largest habitat by volume: dark, cold, high-pressure.", "Runs on marine snow plus vents, seeps, whale falls.", "Extreme adaptations: lures, huge jaws, pressure-proof biochemistry.", "Biodiversity high and mostly undescribed.", "Deep-sea mining is the defining conservation question."], "reqs": ["Depth-rated observation/sampling platform.", "Baseline biodiversity survey before any disturbance.", "Plume and recovery modeling for impacts."], "stds": ["Deep-sea imaging transects per standard protocols.", "Mining impact assessment per ISA guidelines."], "cites": ["Gage JD, Tyler PA. Deep-Sea Biology. Cambridge University Press; 1991.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Pressure with depth in the deep sea.\"\"\"\nprint(\" depth (m)   pressure (atm)   zone\")\nfor z, zone in ((1000, \"bathypelagic\"), (4000, \"abyssal\"),\n                (6000, \"hadal\"), (10935, \"Challenger Deep\")):\n    print(f\"  {z:5d}       {1+z/10:5.0f}        {zone}\")\n"}, {"tier": "Foundations", "g": "Marine Life", "title": "Bioluminescence", "desc": "Bioluminescence - living light from luciferin-luciferase chemistry - is the deep sea's commonest visual signal: most animals below 500 m make light. Uses include lures (anglerfish), counter-illumination camouflage (squids erasing their silhouette), startling predators (the vampire squid's light show), and communication (flashlight fish signaling).\nDinoflagellates make waves glow; firefly squid light Japanese bays; dragonfish see their own red light invisible to prey. The chemistry evolved independently dozens of times. Biomedical science borrowed it: green fluorescent protein (GFP, Nobel 2008) from a jellyfish now labels cells worldwide, and luciferase reporters track gene expression.", "how": "Biologists observe bioluminescence with low-light cameras on ROVs, measure spectra and kinetics in the lab, and test function with behavioral experiments. They purify luciferases for assays - the same enzymes now sold as reporter kits. Ecologists map flashing patterns to species for biodiversity surveys. The GFP story is the model for bioprospecting: basic deep-sea curiosity becoming a universal research tool.", "keys": ["Luciferin-luciferase chemistry makes living light.", "Most deep-sea animals below 500 m produce light.", "Uses: lures, camouflage, startling, communication.", "GFP (Nobel 2008) came from a glowing jellyfish.", "Evolved independently dozens of times."], "reqs": ["Low-light observation capability.", "Spectral measurement for ID.", "Behavioral context for function."], "stds": ["Bioluminescence spectra per standard spectrometry.", "Reporter assays per molecular biology protocols."], "cites": ["Haddock SHD, Moline MA, Case JF. Bioluminescence in the sea. Ann Rev Mar Sci 2:443-493; 2010.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Counter-illumination: matching downwelling light.\"\"\"\n# squid adjusts ventral photophores to background radiance\nbackground = [100, 50, 20, 5, 1]  # decreasing with depth\nprint(\" depth rank   background   photophore output\")\nfor i, b in enumerate(background):\n    print(f\"     {i}          {b:3d}          {b} (matched)\")\n"}, {"tier": "Compounded", "g": "Threats & Change", "title": "Coral Bleaching Mechanisms", "desc": "Coral bleaching is the breakdown of the coral-zooxanthellae symbiosis under heat stress: temperatures ~1-2 C above summer maxima damage the algae's photosystems, producing reactive oxygen species that turn toxic. The coral expels its symbionts - losing color (bleaching) and its main food source. Brief bleaching is survivable; prolonged heat starves the coral.\nMass bleaching events now strike with marine heatwaves - 2014-2017 bleached reefs globally, and the Great Barrier Reef has bleached repeatedly since. Some corals shuffle to heat-tolerant symbiont strains (Symbiodinium clade D); some reefs show adaptation. But the trend is stark: without emissions cuts, annual severe bleaching becomes the norm on most reefs this century, outpacing recovery.", "how": "Scientists predict bleaching with NOAA Coral Reef Watch degree-heating-weeks (DHW): 4 DHW warns, 8 DHW expects mass bleaching and mortality. They monitor in the water with bleaching surveys and temperature loggers, and study tolerance mechanisms in labs - symbiont shuffling, heat-hardening, selective breeding for restoration. Management buys time by cutting local stressors (overfishing of herbivores, runoff) so reefs enter heatwaves as healthy as possible.", "keys": ["Heat damages algal photosystems; toxic oxygen radicals trigger expulsion.", "Bleached = symbiont-free: colorless and starving.", "Degree-heating-weeks predict events: 4 warns, 8 kills.", "Some corals shuffle to heat-tolerant symbionts.", "Annual severe bleaching looms without emissions cuts."], "reqs": ["Sea-surface temperature vs local bleaching threshold.", "DHW accumulation tracking.", "Symbiont clade and coral species ID."], "stds": ["Bleaching alerts per NOAA Coral Reef Watch.", "Bleaching surveys per standard reef-monitoring protocols."], "cites": ["Hughes TP et al. Global warming and recurrent mass bleaching of corals. Nature 543:373-377; 2017.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Degree heating weeks accumulation.\"\"\"\n# DHW sums weekly anomalies above bleaching threshold\nthreshold = 29.5\nweekly_sst = [29.0, 29.6, 30.2, 30.8, 31.0, 30.5, 29.8, 29.2]\ndhw = sum(max(0, sst - threshold) for sst in weekly_sst)\nprint(f\"DHW = {dhw:.1f}\")\nprint(\"Bleaching likely\" if dhw >= 4 else \"No alert\")\n"}, {"tier": "Compounded", "g": "Threats & Change", "title": "Ocean Acidification", "desc": "The ocean absorbs about a quarter of human CO2 emissions, and the chemistry is inexorable: CO2 + H2O forms carbonic acid, lowering pH (already ~0.1 units since preindustrial - a 30% acidity rise) and depleting carbonate ions. Calcifiers - corals, oysters, pteropods, coccolithophores - build shells from carbonate; less carbonate means harder shells, slower growth, and dissolution.\nPteropods, the sea butterflies feeding salmon and whales, already show shell pitting in the Southern Ocean. Oyster hatcheries in the Pacific Northwest suffered larval die-offs tied to upwelled acidified water - the industry's canary. Unlike warming, acidification cannot be adapted away locally: only emissions cuts change the chemistry, though seagrass beds and kelp locally buffer pH on small scales.", "how": "Chemists track acidification with high-precision pH, alkalinity, and pCO2 time series, computing aragonite saturation state - the master variable for calcifiers. Biologists run CO2-perturbation experiments (mesocosms to lab cultures) measuring calcification, growth, and survival across life stages. Hatcheries now monitor incoming water chemistry and buffer or time intakes around upwelling. Policy relevance is direct: saturation-state maps show where shellfisheries face uninhabitable chemistry first.", "keys": ["Ocean absorbs ~25% of human CO2; pH down ~0.1 units already.", "Less carbonate ion = harder shells for calcifiers.", "Pteropods and oyster larvae are the early victims.", "Only emissions cuts fix the chemistry globally.", "Aragonite saturation state is the master variable."], "reqs": ["Two carbonate-system parameters for full calculation.", "Aragonite/calcite saturation states.", "Life-stage-specific biological response data."], "stds": ["Carbonate chemistry per Dickson best practices.", "OA experiments per Riebesell et al. guide to best practices."], "cites": ["Doney SC et al. Ocean acidification: the other CO2 problem. Ann Rev Mar Sci 1:169-192; 2009.", "Gattuso JP, Hansson L, eds. Ocean Acidification. Oxford University Press; 2011."], "demo": "#!/usr/bin/env python3\n\"\"\"pH change from rising atmospheric CO2 (illustrative).\"\"\"\n# dpH ~ -log10(pCO2/pCO2_ref) scaled; simplified Revelle hint\nimport math\npH_ref, pCO2_ref = 8.15, 280.0\nfor pCO2 in (280, 400, 560, 800):\n    pH = pH_ref - 0.9 * math.log10(pCO2 / pCO2_ref)\n    print(f\"  {pCO2:3.0f} ppm CO2 -> pH {pH:.2f}\")\n"}, {"tier": "Compounded", "g": "Ocean Processes", "title": "Upwelling and Nutrient Cycles", "desc": "Upwelling brings deep, nutrient-rich water to the sunlit surface where phytoplankton bloom: Eastern boundary systems (California, Peru, Benguela, Canary) cover <1% of ocean area but yield ~20% of fish catch. Wind pushes surface water offshore (Ekman transport); deep water rises to replace it, loaded with nitrate, phosphate, and silicate.\nThe Peru system feeds the world's largest single fishery (anchoveta); El Nino shuts down upwelling and collapses it, starving seabirds and fishermen alike. Nutrients cycle through uptake, grazing, sinking, and remineralization by bacteria - the biological pump's engine room. Iron limits the subarctic Pacific and Southern Ocean despite abundant macronutrients (HNLC regions).", "how": "Oceanographers map upwelling with wind data, sea-surface temperature (cold tongues), and chlorophyll from satellites; they measure nutrients on hydrographic sections. Fisheries scientists link upwelling indices to recruitment success. Climate researchers watch eastern-boundary systems for warming-driven stratification that could throttle nutrient supply - the hypothesized productivity decline. Iron-addition experiments confirmed HNLC limitation and its geoengineering debate.", "keys": ["Wind-driven upwelling fertilizes <1% of ocean, ~20% of catch.", "Ekman transport moves surface water offshore; deep water rises.", "El Nino shutdowns collapse the Peru anchoveta fishery.", "Iron limits HNLC regions despite abundant N and P.", "Nutrients cycle: uptake, grazing, sinking, remineralization."], "reqs": ["Wind stress and coastline geometry.", "Nutrient profiles and chlorophyll fields.", "ENSO phase for interannual context."], "stds": ["Upwelling indices per NOAA environmental protocols.", "Nutrient analysis per JGOFS methods."], "cites": ["Chavez FP, Messié M. A comparison of eastern boundary upwelling ecosystems. Prog Oceanogr 83:80-96; 2009.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Ekman transport from alongshore wind (illustrative).\"\"\"\n# M = tau / (rho*f)\nrho, f = 1025.0, 8e-5  # kg/m3, Coriolis at ~35 deg\nfor tau in (0.05, 0.1, 0.2):\n    M = tau / (rho * f)\n    print(f\"  wind stress {tau:.2f} N/m2 -> offshore transport {M:.1f} m2/s\")\n"}, {"tier": "Compounded", "g": "Ocean Processes", "title": "The Biological Carbon Pump", "desc": "The biological carbon pump moves surface carbon to the deep ocean: phytoplankton fix CO2, zooplankton and fish package it into fecal pellets and bodies, and gravity plus migration carry it down. Of ~50 gigatonnes fixed yearly, a few gigatonnes sink below 1000 m - sequestered for centuries. Without the pump, atmospheric CO2 would be roughly twice today's.\nEfficiency varies: ballast minerals (silica, carbonate) speed sinking; most particles are remineralized shallow by bacteria. The pump's strength sets the ocean's carbon storage and may weaken as warming stratifies the surface, slowing nutrient return. Geoengineering proposals to fertilize the pump (iron addition) founder on efficiency doubts and ecological side effects.", "how": "Biogeochemists quantify export with sediment traps, thorium-234 disequilibrium, and autonomous floats measuring particle flux; satellites estimate production. They partition the pump into gravitational settling, migrant transport (diel migrators), and mixing. Models embed pump efficiency to project ocean carbon uptake under warming. Field programs (EXPORTS and successors) chase the full budget from surface production to deep sequestration.", "keys": ["Surface CO2 to deep storage via sinking particles and migrants.", "A few Gt/year sink deep - sequestered for centuries.", "Without the pump, atmospheric CO2 would roughly double.", "Ballast minerals speed sinking; bacteria remineralize shallow.", "Warming stratification may weaken the pump."], "reqs": ["Primary production and export flux measurements.", "Particle sinking-speed and remineralization rates.", "Stratification trend data."], "stds": ["Export flux per thorium-234 JGOFS protocols.", "Sediment-trap deployments per standard methods."], "cites": ["Falkowski PG et al. The global carbon cycle: a test of our knowledge. Science 290:291-296; 2000.", "Boyd PW et al. Mesoscale iron enrichment experiments 1993-2005. Science 315:612-617; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Export efficiency: fraction reaching depth.\"\"\"\nimport math\n# Martin curve: F(z) = F100*(z/100)^-b\nF100, b = 1.0, 0.86\nprint(\" depth (m)   fraction of export flux\")\nfor z in (100, 500, 1000, 2000, 4000):\n    print(f\"  {z:4d}        {(z/100)**-b:.3f}\")\n"}, {"tier": "Compounded", "g": "Ecosystems", "title": "Marine Food Web Dynamics", "desc": "Marine food webs route energy from phytoplankton through grazers to top predators, with roughly 10% transfer efficiency per trophic level - which is why top predators are rare and fisheries target low trophic levels for volume. Trophic cascades propagate: overfishing cod released shrimp and crab in the Northwest Atlantic; removing sharks can restructure reef fish communities.\nFishing down the food web - sequentially depleting top predators - leaves systems dominated by smaller, faster-growing species. Jellyfish blooms may signal such simplification. Stable-isotope analysis (nitrogen-15 enriches ~3.4 per mille per level) maps who eats whom without stomach contents. Ecosystem models (Ecopath/Ecosim) test management scenarios across the whole web.", "how": "Ecologists combine diet studies, stable isotopes, and tagging to map trophic links, then build mass-balance models (Ecopath) ensuring production meets consumption at every level. They test fishing scenarios in Ecosim before fleets do it for real. Indicators like mean trophic level of catch track fishing-down over decades. Management is shifting from single species to ecosystem reference points that account for predator needs - forage fish left for whales and seabirds.", "keys": ["~10% transfer efficiency per trophic level.", "Trophic cascades: removing predators restructures communities.", "Fishing down the food web simplifies systems.", "Nitrogen-15 maps trophic position (~3.4 per mille per level).", "Ecopath/Ecosim models test management scenarios."], "reqs": ["Diet/isotope data across trophic levels.", "Production and consumption rates per group.", "Fisheries catch by species over time."], "stds": ["Trophic modeling per Ecopath conventions.", "Stable-isotope analysis per standard lab protocols."], "cites": ["Pauly D et al. Fishing down marine food webs. Science 279:860-863; 1998.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Trophic pyramid: biomass at 10% efficiency.\"\"\"\nprod = 10000.0  # tonnes phytoplankton\nlevels = [\"phytoplankton\", \"zooplankton\", \"small fish\", \"large fish\", \"top predator\"]\nfor i, name in enumerate(levels):\n    print(f\"  {name:14s}: {prod:8.1f} t\")\n    prod *= 0.10\n"}, {"tier": "Compounded", "g": "Ecosystems", "title": "Symbiosis in the Sea", "desc": "The sea runs on partnerships: coral-zooxanthellae (photosynthesis for shelter), cleaner fish and shrimp servicing clients at cleaning stations, anemonefish defended by anemone stings, pistol shrimp sharing burrows with watchman gobies, tubeworms farming chemosynthetic bacteria at vents, bobtail squid culturing glowing Vibrio for camouflage.\nMutualisms, commensalisms, and parasitisms intergrade - cleaner fish sometimes cheat and bite clients; the same symbiont can be mutualist or parasite by context. Symbiosis drives major transitions: mitochondria and chloroplasts were engulfed bacteria. In reefs, the whole ecosystem is a symbiosis stack, which is why bleaching (symbiosis breakdown) collapses the system.", "how": "Marine biologists test symbiosis with removal experiments (exclude cleaners, watch parasite loads), stable isotopes tracing nutrient exchange, and molecular ID of partners. They quantify costs and benefits to place each interaction on the mutualism-parasitism spectrum. Restoration uses symbiosis - probiotic bacteria dosing to heat-proof corals is an active research front. Understanding partnerships predicts which interactions climate change will break first.", "keys": ["Corals, cleaners, anemonefish, vent tubeworms: partnerships everywhere.", "Mutualism to parasitism is a spectrum, context-dependent.", "Organelles were ancient symbioses.", "Reefs are symbiosis stacks - bleaching collapses them.", "Probiotics for corals: applied symbiosis research."], "reqs": ["Partner identification (molecular).", "Cost-benefit measurement for each partner.", "Experimental manipulation (removal/addition)."], "stds": ["Symbiont ID per molecular barcoding standards.", "Mutualism experiments per standard ecological design."], "cites": ["Douglas AE. The Symbiotic Habit. Princeton University Press; 2010.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Mutualism: partner growth with and without symbiont.\"\"\"\n# logistic growth boosted by partner\nr_alone, r_with = 0.10, 0.16\nK = 100.0\nN_alone = N_with = 10.0\nfor _ in range(30):\n    N_alone += r_alone * N_alone * (1 - N_alone / K)\n    N_with += r_with * N_with * (1 - N_with / K)\nprint(f\"Alone: {N_alone:.0f}, with partner: {N_with:.0f} (K={K:.0f})\")\n"}, {"tier": "Compounded", "g": "Marine Life", "title": "Fish Migration and Spawning", "desc": "Fish migrations move biomass across oceans: salmon return from sea to natal rivers (anadromy), eels do the reverse (catadromy), tunas cross basins following temperature fronts, herring and anchovies shift with upwelling. Spawning aggregations gather thousands at predictable sites and moons - groupers, snappers, bumphead parrotfish - making them spectacularly vulnerable to fishing.\nLarval dispersal connects populations: currents carry larvae tens to hundreds of kilometers, so marine reserves must be networked, not isolated. Otolith (ear-stone) chemistry reconstructs individual migration histories like flight recorders. Climate shifts are moving spawning grounds poleward, scrambling management boundaries drawn for stationary stocks.", "how": "Fisheries biologists tag with conventional, acoustic, and satellite tags; they read otolith microchemistry for life-history reconstruction and use genetics for stock structure. Spawning aggregations are surveyed by divers and acoustics, then protected by seasonal closures - the highest-leverage conservation action for reef fisheries. Larval-dispersal models (biophysical, current-driven) design reserve networks with the connectivity larvae actually use.", "keys": ["Anadromous, catadromous, oceanic: migrations cross entire basins.", "Spawning aggregations are predictable - and fishable.", "Larval dispersal sets reserve-network design.", "Otolith chemistry reconstructs individual migrations.", "Warming moves spawning grounds; management boundaries lag."], "reqs": ["Tagging or otolith data for movement.", "Spawning site and timing inventory.", "Current fields for dispersal modeling."], "stds": ["Tagging per standard fisheries protocols.", "Otolith analysis per ICES methods."], "cites": ["Harden Jones FR. Fish Migration. Edward Arnold; 1968.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Larval dispersal distance from current speed and duration.\"\"\"\nspeed_ms, days = 0.2, 30  # m/s, pelagic larval duration\ndist_km = speed_ms * days * 86400 / 1000\nprint(f\"At {speed_ms} m/s for {days} days: ~{dist_km:.0f} km dispersal\")\nprint(\"Reserve spacing must be << this for connectivity.\")\n"}, {"tier": "Compounded", "g": "Marine Life", "title": "Cephalopod Intelligence", "desc": "Octopuses, cuttlefish, and squid are the ocean's most intelligent invertebrates: large brains, camera eyes rivaling vertebrates, and problem-solving - opening jars, navigating mazes, using tools (coconut-carrying octopuses). Cuttlefish pass delayed-gratification tests; octopuses learn by observation.\nTheir skin is a living display: chromatophores, iridophores, and leucophores under neural control produce camouflage, signaling, and the passing-cloud displays of hunting cuttlefish - all in milliseconds, despite colorblind eyes. Short lives (1-2 years for most) make them ecological sprinters, booming and busting with conditions. Fisheries for squid and cuttlefish are major globally, managed with scant data on these fast, smart animals.", "how": "Behavioral biologists run maze, puzzle-box, and learning experiments in aquaria; field workers track with tags and observe dens. Camouflage is studied with spectrometry matching skin to background. Neuroscientists map their distributed nervous system - two-thirds of neurons in the arms. Welfare science now treats cephalopods as sentient (EU protection since 2013), changing lab practice. Fisheries assessment struggles with their short, variable life cycles.", "keys": ["Large brains, camera eyes, problem-solving: top invertebrate minds.", "Skin display: chromatophores under neural control, millisecond changes.", "Colorblind yet master camouflagers - polarization may explain it.", "Short lives make them ecological sprinters.", "Recognized as sentient in EU lab law since 2013."], "reqs": ["Behavioral assay design (maze, puzzle box).", "Spectrometry for camouflage matching.", "Welfare-compliant holding conditions."], "stds": ["Cephalopod welfare per EU Directive 2010/63.", "Behavioral protocols per standard ethology practice."], "cites": ["Hanlon RT, Messenger JB. Cephalopod Behaviour. 2nd ed. Cambridge University Press; 2018.", "Godfrey-Smith P. Other Minds. Farrar, Straus and Giroux; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"Learning curve: trials to criterion (illustrative).\"\"\"\n# octopus maze: errors decline exponentially\nimport math\nprint(\" trial   errors\")\nfor t in range(1, 11):\n    print(f\"   {t:2d}      {20*math.exp(-0.5*t):5.1f}\")\n"}, {"tier": "Compounded", "g": "Ocean Zones", "title": "Intertidal Zone Ecology", "desc": "The intertidal - between high and low tide - is ecology's classic laboratory: steep gradients of exposure, temperature, and predation compress into meters. Paine's starfish removal experiment here founded the keystone-species concept: without Pisaster, mussels overran the community. Connell's barnacle work revealed competition's role in zonation.\nOrganisms endure desiccation, thermal shock, and wave battering with shells, clustering, and timing activity to immersion. Zonation patterns - barnacles high, mussels mid, kelps low on exposed shores - reflect physical stress above and biological interactions below. Long-term intertidal monitoring now detects climate shifts: warm-water species creeping poleward, heatwave mass mortalities.", "how": "Intertidal ecologists work the low-tide window with quadrats and transects, run removal and caging experiments to separate competition from predation, and log temperature with biomimetic sensors (robo-mussels). They track range shifts with resurveys of historic sites. The zone's accessibility makes it ideal for long-term, high-replication experiments - and for teaching ecology where the evidence is literally underfoot.", "keys": ["Steep gradients compress ecology into meters.", "Paine's starfish removal founded the keystone concept.", "Zonation: physical stress above, biology below.", "Adaptations: shells, clustering, timing to immersion.", "Long-term monitoring detects climate-driven shifts."], "reqs": ["Tide tables for safe, timed access.", "Permanent transect markers for resurvey.", "Temperature loggers (biomimetic where possible)."], "stds": ["Intertidal surveys per MARINe protocols.", "Experimental design per standard ecological methods."], "cites": ["Paine RT. Food web complexity and species diversity. Am Nat 100:65-75; 1966.", "Connell JH. The influence of interspecific competition. Ecology 42:710-723; 1961."], "demo": "#!/usr/bin/env python3\n\"\"\"Keystone effect: diversity with and without predator.\"\"\"\n# Shannon diversity hint: predator maintains evenness\nimport math\nwith_pred = [20, 18, 15, 12, 10, 8, 7, 5, 3, 2]\nwithout = [70, 8, 6, 5, 4, 3, 2, 1, 1, 0]\ndef shannon(ab):\n    tot = sum(ab)\n    return -sum((n/tot)*math.log(n/tot) for n in ab if n > 0)\nprint(f\"With starfish: H={shannon(with_pred):.2f}; without: H={shannon(without):.2f}\")\n"}, {"tier": "Compounded", "g": "Ecosystems", "title": "Estuary Ecosystems", "desc": "Estuaries - where rivers meet the sea - are among the most productive ecosystems on Earth: nutrient-loaded fresh water mixes with the sea over shallow, sunlit bottoms, fueling marshes, seagrass, oyster reefs, and nursery grounds. Chesapeake Bay, the Humber, the Severn: names that mean seafood.\nSalinity gradients structure communities from fresh to marine; turbidity maximum zones trap particles and larvae. Oyster reefs - built by a keystone filter-feeder - once filtered entire bays in days; overharvest and disease collapsed them, and restoration rebuilds the filtration engine. Estuaries take the hit for watersheds: eutrophication, dead zones, and contaminants arrive with the river.", "how": "Estuarine scientists run salinity-nutrient transects, trawl nursery grounds, and core sediments for history. Oyster restoration sets spat on shell in sanctuaries, measuring filtration recovery. Watershed management - nutrient caps like Chesapeake's TMDL - addresses eutrophication at its source. Living-shoreline projects replace bulkheads with marshes and reefs, trading hard armor for habitat that also protects.", "keys": ["River meets sea: maximum productivity, maximum nursery value.", "Salinity gradients structure the communities.", "Oyster reefs are filtration engines - restoration rebuilds them.", "Estuaries inherit watershed problems: nutrients, dead zones.", "Living shorelines replace bulkheads with habitat."], "reqs": ["Salinity and nutrient transects.", "Nursery-ground trawl surveys.", "Watershed loading inventory."], "stds": ["Estuarine monitoring per EPA NCA protocols.", "Oyster restoration per TNC guidance."], "cites": ["Day JW et al. Estuarine Ecology. 2nd ed. Wiley; 2012.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Oyster filtration: bay turnover time.\"\"\"\nbay_L = 7e13  # liters, Chesapeake-ish\noysters = 1e9\nfilt_L_per_day = 190  # per oyster\ndays = bay_L / (oysters * filt_L_per_day)\nprint(f\"{oysters:.0e} oysters filter the bay in ~{days:.0f} days\")\n"}, {"tier": "Compounded", "g": "Marine Life", "title": "Marine Larval Dispersal", "desc": "Most marine animals disperse as larvae: tiny, planktonic, at the mercy of currents for days to months. Pelagic larval duration sets dispersal scale - hours for some corals, a year for spiny lobsters. This dispersing stage connects populations, rescues depleted reefs, and frustrates fisheries management drawn on adult ranges.\nLarvae are not passive: vertical migration into favorable currents, sensory settlement cues (sound of reefs, chemical signatures), and surprising swimming ability shape where they land. Parentage genetics and otolith chemistry now measure real dispersal, often shorter than models predict - retention near home is common. Reserve design uses dispersal kernels to space protected areas within larval reach.", "how": "Larval ecologists combine biophysical models (currents + behavior) with empirical parentage analysis - genotyping recruits to find their parents' reef. They measure pelagic durations in rearing experiments and settlement cues in choice chambers. Connectivity matrices from models and genetics guide MPA network design: spacing, size, and placement so larvae flow between reserves. Climate-driven current shifts are redrawing the maps.", "keys": ["Planktonic larvae connect marine populations across distance.", "Pelagic duration sets scale: hours to a year.", "Larvae swim, migrate vertically, and choose settlement cues.", "Real dispersal is often shorter than passive models predict.", "Reserve networks are spaced by dispersal kernels."], "reqs": ["Pelagic larval duration for the species.", "Current fields for the spawning season.", "Genetic or otolith validation data."], "stds": ["Parentage analysis per standard population-genetics methods.", "Biophysical modeling per CMS conventions."], "cites": ["Cowen RK, Sponaugle S. Larval dispersal and marine population connectivity. Ann Rev Mar Sci 1:443-466; 2009.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Dispersal kernel: settlement vs distance from source.\"\"\"\nimport math\n# exponential kernel, mean dispersal 20 km\nmean_km = 20.0\nprint(\" distance (km)   fraction settling\")\nfor d in (5, 10, 20, 40, 80):\n    frac = math.exp(-d / mean_km) / mean_km * 10  # per 10-km band hint\n    print(f\"    {d:3d}            {frac:.3f}\")\n"}, {"tier": "Compounded", "g": "Ocean Zones", "title": "Whale Fall Ecosystems", "desc": "When a whale dies and sinks, its carcass becomes a deep-sea oasis: hagfish and sleeper sharks strip the flesh in months (mobile-scavenger stage), then bone-eating Osedax worms and snails work the skeleton for years (enrichment stage), and finally sulfur-oxidizing bacteria sustain a chemosynthetic community for decades (sulfophilic stage).\nWhale falls host endemic species found nowhere else and may have served as evolutionary stepping stones to hydrothermal vents. Scientists now sink carcasses deliberately (or tow stranded whales out) to study succession. Whaling removed countless falls - an invisible deep-sea impact of the slaughter, reducing the food pulses the abyss evolved with.", "how": "Researchers locate falls by following scavenger aggregations or deploy carcasses experimentally, then monitor succession with time-lapse cameras, ROVs, and colonization experiments over years. They describe the endemic fauna - Osedax was unknown before whale-fall work - and compare communities across ocean basins. Isotope analysis traces whale carbon through the food web. The work reframes whaling's damage: not just fewer whales, but a starved deep sea.", "keys": ["Dead whales become deep-sea oases in three successional stages.", "Osedax bone worms and chemosynthetic bacteria are fall specialists.", "Possible evolutionary stepping stones to vent communities.", "Whaling removed the food pulses the abyss evolved with.", "Experimental falls reveal succession over years."], "reqs": ["Located or deployed carcass.", "Long-term observation platform (years).", "Taxonomic expertise for endemic fauna."], "stds": ["Succession staging per Smith & Baco framework.", "Specimen preservation per deep-sea protocols."], "cites": ["Smith CR, Baco AR. Ecology of whale falls at the deep-sea floor. Oceanogr Mar Biol Ann Rev 41:311-354; 2003.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Whale-fall succession timeline.\"\"\"\nstages = [(\"mobile scavengers\", \"0-4 months\"), (\"enrichment opportunists\", \"4 mo - 2 yr\"),\n          (\"sulfophilic chemosynthetic\", \"2-50+ years\")]\nfor name, span in stages:\n    print(f\"  {name:28s}: {span}\")\n"}, {"tier": "Advanced", "g": "Ocean Zones", "title": "Hydrothermal Vent Communities", "desc": "Hydrothermal vents - discovered in 1977 - host ecosystems powered by chemosynthesis, not sunlight: bacteria oxidize hydrogen sulfide from superheated vent fluid, and giant tubeworms (Riftia), clams, and shrimp farm them in gills or guts. Black smokers chimney at 350 C; the animals thrive in gradients from boiling to near-freezing within centimeters.\nVent fields are ephemeral - individual vents last decades - so larvae must find new sites across barren abyss, dispersing along ridge axes. Endemism is extreme: most vent species occur nowhere else. Mining interests target seafloor massive sulfides at vent fields, pitting mineral wealth against irreplaceable ecosystems in the International Seabed Authority's defining debate.", "how": "Vent biologists map fields with AUVs, sample with ROV manipulators and slurp guns, and run in-situ experiments on colonization and physiology. They trace chemosynthetic production with isotopes and model larval dispersal along ridges to predict connectivity. Impact assessment for mining demands baseline biodiversity inventories - largely undescribed - and plume modeling. Some vent fields are proposed as protected areas; the science races the mining applications.", "keys": ["Chemosynthesis, not photosynthesis, powers vent ecosystems.", "Giant tubeworms farm sulfur bacteria in their tissues.", "Vents are ephemeral; larvae disperse along ridge axes.", "Endemism extreme - most species occur nowhere else.", "Seafloor massive-sulfide mining threatens vent fields."], "reqs": ["High-resolution ridge-axis mapping.", "ROV sampling and in-situ experimentation.", "Baseline biodiversity inventory before any mining."], "stds": ["Vent-fauna taxonomy per standard deep-sea protocols.", "Mining EIA per ISA guidelines."], "cites": ["Van Dover CL. The Ecology of Deep-Sea Hydrothermal Vents. Princeton University Press; 2000.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Vent fluid mixing: temperature vs distance (illustrative).\"\"\"\n# exponential dilution of 350 C fluid into 2 C seawater\nimport math\nprint(\" distance (m)   T (C)\")\nfor x in (0, 1, 5, 20, 100):\n    T = 2 + 348 * math.exp(-x / 8)\n    print(f\"    {x:3d}        {T:6.1f}\")\n"}, {"tier": "Advanced", "g": "Ocean Zones", "title": "Cold Seep Ecosystems", "desc": "Cold seeps leak methane and hydrogen sulfide from sediments - at continental margins, mud volcanoes, and brine pools - fueling chemosynthetic communities like vents but without the heat: mussel beds, tubeworm bushes, and microbial mats. Seeps are longer-lived and more widespread than vents.\nMethane-eating archaea and bacteria form the base, sometimes in symbiosis with the mussels and worms; authigenic carbonate rocks precipitate as byproduct, building lasting habitat. Seeps link to climate through methane - a potent greenhouse gas - and to the deep biosphere beneath the seafloor. Brine pools, dense hypersaline lakes on the seafloor, ring their shores with mussels in one of the strangest ecotones on Earth.", "how": "Seep researchers map with multibeam sonar (bubble plumes show in the water column), ground-truth with ROVs, and core sediments for methane fluxes and microbial communities. They measure chemosynthetic production with isotope tracers and model methane fate - how much reaches the atmosphere vs is consumed. Long-term observatories watch seep dynamics over years. Like vents, seeps face emerging pressures from bottom trawling and drilling.", "keys": ["Methane and sulfide seeps fuel chemosynthesis without heat.", "Mussel beds, tubeworm bushes, microbial mats: the seep community.", "Longer-lived and more widespread than vents.", "Methane fate links seeps to climate.", "Brine pools ring hypersaline lakes with life."], "reqs": ["Multibeam water-column anomaly mapping.", "Sediment cores for methane flux.", "ROV ground-truthing."], "stds": ["Seep mapping per standard hydroacoustic protocols.", "Methane flux per benthic-chamber methods."], "cites": ["Levin LA. Ecology of cold seep sediments. Oceanogr Mar Biol Ann Rev 43:1-46; 2005.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Seep methane: fraction consumed vs escaping (illustrative).\"\"\"\nflux = 100.0  # mol/m2/yr\nconsumed_frac = 0.85  # anaerobic oxidation of methane\nprint(f\"Flux {flux} mol/m2/yr: {flux*consumed_frac:.0f} consumed, {flux*(1-consumed_frac):.0f} escapes\")\n"}, {"tier": "Advanced", "g": "Conservation", "title": "Marine Protected Area Design", "desc": "Marine protected areas (MPAs) shelter biodiversity and rebuild fisheries when designed well: no-take reserves show more, bigger fish within years, spilling over to surrounding fisheries. Design principles are quantitative - size matched to species home ranges, spacing within larval dispersal distance, replication across habitats, and protection of critical life stages.\nPaper parks - designated but unenforced - protect nothing; effective MPAs need surveillance, community buy-in, and sustainable financing. Networks outperform isolated reserves through connectivity. The global 30x30 target (protect 30% by 2030) drives current expansion, with science advising where protection buys the most biodiversity and climate resilience per area.", "how": "Planners run systematic conservation planning (Marxan and successors) optimizing biodiversity coverage against cost and conflict, informed by habitat maps, species distributions, and connectivity models. They engage fishers and communities early - compliance decides outcomes. Monitoring (inside vs outside, before vs after) tests effectiveness and adapts boundaries. Enforcement mixes patrols, vessel tracking, and community reporting; financing increasingly uses conservation trust funds and blue bonds.", "keys": ["Well-designed no-take reserves rebuild fish fast, spilling over.", "Design rules: size, spacing, replication, life-stage coverage.", "Paper parks protect nothing - enforcement decides.", "Networks beat isolated reserves through connectivity.", "30x30 target drives science-based expansion."], "reqs": ["Habitat and species distribution maps.", "Connectivity/dispersal data.", "Stakeholder engagement and enforcement plan."], "stds": ["MPA planning per IUCN categories.", "Effectiveness monitoring (BACI design)."], "cites": ["Lubchenco J et al. Plugging a hole in the ocean: the emerging science of marine reserves. Ecol Appl 13:S3-S7; 2003.", "Gaines SD et al. Designing marine reserve networks for both conservation and fisheries management. PNAS 107:18286-18293; 2010."], "demo": "#!/usr/bin/env python3\n\"\"\"Reserve spacing vs larval dispersal (design rule).\"\"\"\n# spacing should be <~2x mean dispersal distance\nfor mean_km in (10, 25, 50, 100):\n    print(f\"  mean dispersal {mean_km:3d} km -> max spacing ~{2*mean_km:3d} km\")\n"}, {"tier": "Advanced", "g": "Conservation", "title": "Fisheries Stock Assessment", "desc": "Stock assessment estimates how many fish can be caught sustainably: population models fit to catch, survey, and age data produce biomass estimates, fishing-mortality rates, and reference points like MSY (maximum sustainable yield). Modern assessments are statistical catch-at-age models run in frameworks like Stock Synthesis.\nUncertainty is structural - data are noisy, models are wrong in detail - so management uses harvest control rules that cut catches automatically when biomass falls. Overfishing is defined against reference points; rebuilding plans set timelines. Illegal, unreported, and unregulated (IUU) fishing undermines assessments by hiding removals. Ecosystem-based management adds predator needs and climate shifts to single-species math.", "how": "Assessment scientists compile catch-at-age, survey indices, and biological parameters, fit models with careful diagnostics (retrospective patterns reveal trouble), and present uncertainty as decision tables - catch options with probabilities of overfishing. Managers set quotas through harvest control rules agreed in advance, reducing political negotiation. Observers and electronic monitoring verify catches; port controls fight IUU. Climate-ready assessment is the frontier: shifting distributions break stationary assumptions.", "keys": ["Models fit to catch, survey, age data give biomass and fishing mortality.", "Reference points (MSY) define overfishing.", "Harvest control rules automate catch cuts when stocks fall.", "IUU fishing hides removals and undermines assessment.", "Uncertainty presented as decision tables, not point estimates."], "reqs": ["Catch-at-age and survey index time series.", "Life-history parameters (growth, maturity, natural mortality).", "Model diagnostics and retrospective analysis."], "stds": ["Assessment per ICES/NOAA stock-assessment standards.", "Reference points per MSY-based frameworks."], "cites": ["Hilborn R, Walters CJ. Quantitative Fisheries Stock Assessment. Chapman & Hall; 1992.", "Quinn TJ, Deriso RB. Quantitative Fish Dynamics. Oxford University Press; 1999."], "demo": "#!/usr/bin/env python3\n\"\"\"Schaefer surplus production: MSY reference points.\"\"\"\n# dB/dt = rB(1-B/K) - C ; MSY = rK/4 at B=K/2\nr, K = 0.4, 1000.0  # per yr, tonnes\nMSY = r * K / 4\nprint(f\"MSY = {MSY:.0f} t at B = {K/2:.0f} t, F = {r/2:.2f}/yr\")\n"}, {"tier": "Advanced", "g": "Research Methods", "title": "eDNA for Marine Monitoring", "desc": "Environmental DNA - genetic traces shed into water - lets scientists detect species from a water sample: filter, extract, amplify marker genes (COI, 12S, 18S), and sequence. A liter of seawater reveals fish communities, invasive species arrivals, and rare whales without seeing them.\nMetabarcoding surveys whole communities; qPCR targets single species (invasive carp, endangered mammals). eDNA decays in days, so detections mean recent presence - but transport by currents smears location, and contamination is the constant enemy. Calibration against visual and catch surveys builds the quantitative bridge from DNA reads to abundance. The method is revolutionizing biodiversity monitoring from ports to the deep sea.", "how": "Practitioners design primers for target taxa, filter water with contamination controls (blanks at every step), and sequence with replication. Bioinformatic pipelines assign reads against reference databases - gaps in the databases limit ID, so barcoding campaigns fill them. They interpret with occupancy models accounting for imperfect detection. Management uses eDNA for early invasive detection, MPA effectiveness checks, and fisheries-independent community surveys.", "keys": ["Shed DNA in water reveals species without observation.", "Metabarcoding surveys communities; qPCR targets species.", "Decays in days: detection means recent presence.", "Currents smear location; contamination is the enemy.", "Reference-database gaps limit identification."], "reqs": ["Contamination controls at every step.", "Validated primers and reference database.", "Occupancy modeling for imperfect detection."], "stds": ["eDNA sampling per national/ICES guidelines.", "Lab workflows per ancient-DNA-grade contamination practice."], "cites": ["Thomsen PF, Willerslev E. Environmental DNA - an emerging tool. Biol Rev 90:485-499; 2015.", "Ruppert KM, Kline RJ, Rahman MS. Past, present, and future of eDNA. J Anim Ecol 88:5-30; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"eDNA decay: detection window after species leaves.\"\"\"\nimport math\nC0, k = 100.0, 0.5  # copies/L, per day\nLOD = 5.0\nt_detect = math.log(C0 / LOD) / k\nprint(f\"Detectable for ~{t_detect:.1f} days after departure\")\n"}, {"tier": "Advanced", "g": "Threats & Change", "title": "Ocean Deoxygenation", "desc": "Ocean oxygen is declining: warming reduces gas solubility and strengthens stratification, cutting ventilation of the interior, while nutrient runoff fuels coastal dead zones. Oxygen minimum zones (OMZs) are expanding; the global ocean has lost ~2% of its oxygen since 1960, with larger losses in some regions.\nHypoxia squeezes habitats - fish and invertebrates flee or die below ~2 mg/L - compressing ecosystems into thinner surface layers and altering food webs. OMZ expansion also boosts nitrous oxide production, a potent greenhouse gas, creating a feedback. Unlike acidification, deoxygenation has local levers: cutting nutrient runoff shrinks dead zones (the Gulf of Mexico hypoxic zone tracks Mississippi nitrogen), while the open-ocean trend needs emissions cuts.", "how": "Oceanographers track oxygen with shipboard Winkler titrations, Argo floats with oxygen sensors (the growing BGC-Argo array), and moorings; models project OMZ futures under warming scenarios. Managers set nutrient-loading caps (TMDLs) to shrink coastal dead zones and monitor recovery. Fisheries adapt to habitat compression - tuna squeezed into surface layers become more catchable, a perverse effect. The Global Ocean Oxygen Network (GO2NE) coordinates the science.", "keys": ["Warming + stratification + runoff = declining ocean oxygen.", "~2% lost since 1960; OMZs expanding.", "Hypoxia below ~2 mg/L kills or displaces marine life.", "Compresses habitats; boosts nitrous oxide feedback.", "Nutrient caps fix coastal zones; emissions fix the open ocean."], "reqs": ["Oxygen profiles (ship, float, mooring).", "Nutrient loading inventory for coastal zones.", "Ventilation/stratification trend data."], "stds": ["Oxygen measurement per GO-SHIP protocols.", "Hypoxia threshold reporting per standard definitions."], "cites": ["Breitburg D et al. Declining oxygen in the global ocean and coastal waters. Science 359:eaam7240; 2018.", "Keeling RF, Kortzinger A, Gruber N. Ocean deoxygenation in a warming world. Ann Rev Mar Sci 2:199-229; 2010."], "demo": "#!/usr/bin/env python3\n\"\"\"Oxygen solubility vs temperature (illustrative).\"\"\"\n# solubility falls ~1.5% per C in this range\nO2_20 = 7.0  # mg/L at 20 C, 35 ppt\nfor T in (10, 15, 20, 25, 30):\n    print(f\"  {T:2d} C: {O2_20*(1+0.015*(20-T)):.2f} mg/L saturation\")\n"}, {"tier": "Advanced", "g": "Threats & Change", "title": "Microplastics in Marine Food Webs", "desc": "Microplastics - fragments under 5 mm from degraded debris, textiles, tires, and microbeads - now pervade the ocean from surface gyres to deep-sea sediments and Arctic ice. Zooplankton, filter feeders, and fish ingest them; laboratory studies show gut blockage, reduced feeding, and chemical transfer, though field population-level effects remain debated.\nPlastics also carry additives (phthalates, flame retardants) and sorb pollutants, making particles chemical vectors. Nanoplastics may cross biological membranes - the least-studied, most-worrying fraction. Monitoring standardizes on trawl and bulk sampling with FTIR/Raman ID. Solutions rank by the waste hierarchy: reduce production and single-use, improve waste management, clean up - with source reduction dwarfing cleanup in impact.", "how": "Researchers sample with manta trawls (surface), pumps and nets (water column), and cores (sediment), identifying polymers by spectroscopy with strict contamination controls (plastic-free protocols, blanks). They quantify ingestion across trophic levels and test effects in dose-response experiments. Policy work tracks the UN plastics treaty negotiations and evaluates interventions - bag bans, microbead bans, extended producer responsibility - against monitoring data.", "keys": ["<5 mm fragments pervade ocean, sediments, ice.", "Ingested across trophic levels; lab effects clear, field effects debated.", "Additives and sorbed pollutants make particles chemical vectors.", "Nanoplastics may cross membranes - least studied, most worrying.", "Source reduction dwarfs cleanup in impact."], "reqs": ["Contamination-controlled sampling and blanks.", "Spectroscopic polymer ID (FTIR/Raman).", "Standardized size fractions for comparability."], "stds": ["Microplastic sampling per NOAA/ICES guidelines.", "Polymer ID per spectroscopic library matching."], "cites": ["GESAMP. Sources, fate and effects of microplastics in the marine environment; 2015.", "Wright SL, Thompson RC, Galloway TS. The physical impacts of microplastics. Environ Pollut 178:483-492; 2013."], "demo": "#!/usr/bin/env python3\n\"\"\"Microplastic concentration unit conversions.\"\"\"\n# trawl: pieces per km2 -> pieces per m3 (net depth 0.2 m)\nfor pieces_km2 in (1000, 50000, 500000):\n    per_m3 = pieces_km2 / 1e6 / 0.2\n    print(f\"  {pieces_km2:6.0f} pieces/km2 ~= {per_m3:.2f} pieces/m3\")\n"}, {"tier": "Advanced", "g": "Conservation", "title": "Coral Restoration Techniques", "desc": "Coral restoration grows hope literally: fragments farmed in underwater or land nurseries, then outplanted to degraded reefs - gardening the sea. Microfragmentation (cutting corals into tiny pieces that fuse and grow fast) accelerates production; larval reseeding captures spawning slicks to settle millions of babies on substrates.\nAssisted evolution pushes further: selective breeding for heat tolerance, symbiont manipulation, and probiotic dosing. Success is measured in survival, growth, and - the hard one - reproduction and reef-scale recovery. Restoration cannot outpace climate change at scale, but it buys time, preserves genetic diversity, and rebuilds reefs where local stressors are fixed. Scaling from plots to kilometers is the field's central challenge.", "how": "Practitioners collect fragments sustainably (donor colonies recover), grow them in nurseries with predator control, and outplant with epoxy or nails during calm seasons. They genotype for diversity and heat tolerance, track survival with tagged colonies, and site projects where local stressors are managed - restoration fails on reefs still being degraded. Larval approaches need spawning prediction and settlement-substrate engineering. Funders increasingly demand survival and cost-per-colony metrics.", "keys": ["Nursery-grown fragments outplanted: gardening the sea.", "Microfragmentation accelerates growth for production.", "Larval reseeding settles millions from spawning slicks.", "Assisted evolution: breeding, symbionts, probiotics for heat.", "Cannot outpace climate at scale - buys time and diversity."], "reqs": ["Donor colony and nursery capacity.", "Outplant site with managed local stressors.", "Genetic diversity and survival tracking."], "stds": ["Restoration monitoring per Reef Futures standards.", "Genetic diversity guidelines per restoration genetics."], "cites": ["Boström-Einarsson L et al. Coral restoration - a systematic review of current methods. PLoS ONE 15:e0226631; 2020.", "National Academies. A Research Review of Interventions to Increase the Persistence of Coral Reefs; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Nursery production: fragments to outplant-ready colonies.\"\"\"\n# exponential growth of fragments\nfrags, growth_per_year, years = 100, 3.0, 2\nsurvival = 0.7\nout = frags * (growth_per_year ** years) * survival\nprint(f\"{frags} fragments -> ~{out:.0f} outplant-ready in {years} yr ({survival*100:.0f}% survival)\")\n"}, {"tier": "Advanced", "g": "Research Methods", "title": "Marine Bioacoustics", "desc": "Sound travels far in water - marine animals evolved to use it, and scientists eavesdrop. Hydrophones record whale songs spanning ocean basins, dolphin echolocation clicks, fish choruses at dusk, and the snapping-shrimp crackle that dominates shallow soundscapes. Passive acoustic monitoring (PAM) watches populations continuously, cheaply, in all weather.\nAnthropogenic noise is the threat: shipping rumble, seismic airguns, naval sonar, pile driving - masking communication, displacing animals, and in beaked whales, causing lethal strandings. Regulation sets exposure thresholds (harassment vs injury), requires monitoring and shutdown zones, and pushes quieter ship design. Soundscape ecology treats the acoustic environment itself as a habitat feature worth protecting.", "how": "Bioacousticians deploy autonomous hydrophones for months, detect calls with algorithms and analysts, and estimate density from call rates or arrays. They assess noise impact with exposure modeling against threshold criteria (e.g., NOAA acoustic guidance). Mitigation includes seasonal restrictions, real-time whale detection triggering ship slowdowns, and bubble curtains around pile driving. Baseline soundscape recording before industrial projects is becoming standard practice.", "keys": ["Sound is the sea's long-distance sense - animals and scientists use it.", "PAM monitors populations continuously in all weather.", "Shipping, seismic, sonar mask and displace marine life.", "Exposure thresholds separate harassment from injury.", "Quieting ships and shutdown zones are the mitigations."], "reqs": ["Calibrated hydrophones with adequate bandwidth.", "Call libraries for automated detection.", "Noise-source characterization for impact assessment."], "stds": ["Underwater noise measurement per ANSI/ISO standards.", "Impact thresholds per NOAA acoustic guidance."], "cites": ["Au WWL, Hastings MC. Principles of Marine Bioacoustics. Springer; 2008.", "Williams R et al. Impacts of anthropogenic noise on marine life. Oceanography 28:198-213; 2015."], "demo": "#!/usr/bin/env python3\n\"\"\"Sonar equation: detection range hint.\"\"\"\n# SL - 2*TL - NL + DI > DT ; TL = 20logR\nimport math\nSL, NL, DT = 180, 70, 10  # dB\nfor R_km in (1, 5, 10, 50):\n    TL = 20 * math.log10(R_km * 1000)\n    SE = SL - 2 * TL - NL\n    print(f\"  {R_km:2d} km: signal excess {SE:+.0f} dB {\"detect\" if SE > DT else \"miss\"}\")\n"}, {"tier": "Advanced", "g": "Threats & Change", "title": "Deep-Sea Mining Ecological Risk", "desc": "Deep-sea mining targets polymetallic nodules (abyssal plains), seafloor massive sulfides (vents), and cobalt crusts (seamounts) for battery and electronics metals. The ecological risk is fundamental: nodule fields took millions of years to form and host slow-growing, endemic fauna; mining removes the hard substrate habitat itself, and sediment plumes smother surroundings.\nRecovery experiments show tracks persisting for decades with little recolonization - on human timescales, effectively permanent loss. The International Seabed Authority writes the mining code for international waters while exploration contracts accumulate. Scientists call for baseline research, protected-area networks (APEIs), and a precautionary pause until impacts are understood - the defining deep-ocean policy fight.", "how": "Impact scientists run baseline biodiversity surveys (largely undescribed fauna), model plume dispersal from collector tests, and monitor experimental disturbances for recovery - decades-long commitments. They design APEIs (Areas of Particular Environmental Interest) as no-mining reference zones. The ISA's environmental regulations, EIAs, and the precautionary approach frame decisions; NGOs and scientists push for a moratorium while contractors push to mine. Every collector test is watched as a policy experiment.", "keys": ["Nodules, sulfides, crusts: battery metals on million-year timescales.", "Mining removes the habitat substrate itself.", "Plumes smother surrounding communities.", "Recovery effectively permanent on human timescales.", "ISA mining code vs precautionary moratorium: the policy fight."], "reqs": ["Baseline biodiversity inventory (years of survey).", "Plume dispersal modeling.", "Long-term recovery monitoring design."], "stds": ["EIA per ISA draft exploitation regulations.", "APEI design per ISA environmental management plans."], "cites": ["Levin LA et al. Defining serious harm to the marine environment in the context of deep-seabed mining. Mar Policy 74:245-259; 2016.", "Castro P, Huber ME. Marine Biology. 11th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Nodule growth vs mining: timescale mismatch.\"\"\"\ngrowth_mm_per_Myr = 5.0  # mm per million years\nnodule_mm = 50.0\nage_Myr = nodule_mm / growth_mm_per_Myr\nprint(f\"A {nodule_mm:.0f} mm nodule is ~{age_Myr:.0f} million years old\")\nprint(\"Mining removes in minutes what took geological time to form.\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-MARBS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||false;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-MARBS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-marine-biology-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('marine-biology',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
